css.content:
/* Marquee: two identical tracks translate by one track width. Decorative motion, so it stops for reduced motion. */
.marquee { display: flex; overflow: hidden; }
.marquee-track { display: flex; flex: none; min-width: 100%; align-items: center; justify-content: space-around; animation: marquee-run var(--marquee-duration, 30s) linear infinite; }
.marquee-reverse .marquee-track { animation-direction: reverse; }
.marquee-pause:hover .marquee-track, .marquee-pause:focus-within .marquee-track { animation-play-state: paused; }
[data-paused] .marquee-track { animation-play-state: paused; }
.marquee-controlled { position: relative; }
.marquee-toggle { position: absolute; z-index: 1; inset-block-start: 0; inset-inline-end: 0; min-height: 24px; padding: 0 var(--s2); border: 1px solid var(--rule); background: var(--background); color: var(--foreground); font: inherit; font-size: var(--text-xs); cursor: pointer; }
.marquee-toggle:focus-visible { outline: var(--focus-ring); outline-offset: 2px; }
@keyframes marquee-run { from { transform: translateX(0); } to { transform: translateX(calc(-100% * var(--dir, 1))); } }
@media (prefers-reduced-motion: reduce) { .marquee-toggle { display: none; } .marquee { flex-wrap: wrap; } .marquee-track { animation: none; flex-wrap: wrap; } .marquee-track[aria-hidden="true"] { display: none; } }

usage:
import {Marquee} from '@monoline/react';

<Marquee duration={20}>
  {['Acme', 'Globex', 'Initech', 'Umbrella', 'Hooli'].map((n) => (
    <span key={n} style={{padding: '0 var(--s5)', fontFamily: 'var(--font-display)'}}>
      {n}
    </span>
  ))}
</Marquee>

source.content:
'use client';
import {forwardRef, useState, type CSSProperties, type HTMLAttributes} from 'react';
import {cx} from '../../utils/cx';

export interface MarqueeProps extends HTMLAttributes<HTMLDivElement> {
  /** Seconds for one full loop. */
  duration?: number | undefined;
  /** Scroll to the right instead of the left. Default false. */
  reverse?: boolean | undefined;
  /** Stop when the pointer is over it or focus is inside. Default true. */
  pauseOnHover?: boolean | undefined;
  /** Show a Pause / Play button so keyboard and touch users can stop the motion (WCAG 2.2.2). Default true; set false only where the motion is purely decorative and you offer another way to stop it. */
  pausable?: boolean | undefined;
}

/** Children scroll left (or right with `reverse`). Keep the items short. */
export const Marquee = forwardRef<HTMLDivElement, MarqueeProps>(function Marquee(
  {duration = 30, reverse, pauseOnHover = true, pausable = true, className, style, children, ...rest},
  ref,
) {
  const [paused, setPaused] = useState(false);
  return (
    <div
      ref={ref}
      data-paused={paused || undefined}
      className={cx(
        'marquee',
        reverse && 'marquee-reverse',
        pauseOnHover && 'marquee-pause',
        pausable && 'marquee-controlled',
        className,
      )}
      style={{'--marquee-duration': `${duration}s`, ...style} as CSSProperties}
      {...rest}
    >
      {pausable && (
        <button type="button" className="marquee-toggle" aria-pressed={paused} onClick={() => setPaused(!paused)}>
          {paused ? 'Play' : 'Pause'}
          <span className="sr-only"> scrolling</span>
        </button>
      )}
      <div className="marquee-track">{children}</div>
      <div className="marquee-track" aria-hidden="true">
        {children}
      </div>
    </div>
  );
});
